/// tag-derived and every metadata value is sanitised.
pub fn copy_to_library(
    downloaded: &[PathBuf],
    library_root: &Path,
    artist: &str,
    album: &str,
) -> Result<LibraryWriteOutcome> {
    let artist_dir = sanitize_component(artist);
    copy_into_library(LibraryWrite {
        downloaded,
        library_root,
        artist_dir: &artist_dir,
